css_template:
.gallery-card[data-style-element-divider="thin_solid"] .hl-sep {
  display: block;
  height: 1px;
  background: var(--card-muted, #ccc);
  border: none;
  margin: 6px 0;
  opacity: 0.4;
}

.gallery-card[data-style-element-divider="double_line"] .hl-sep {
  display: block;
  height: 3px;
  border: none;
  border-top: 1px solid var(--card-muted, #ccc);
  border-bottom: 1px solid var(--card-muted, #ccc);
  background: transparent;
  margin: 6px 0;
  opacity: 0.5;
}

.gallery-card[data-style-element-divider="dotted_line"] .hl-sep {
  display: block;
  height: 0;
  border-top: 1px dotted var(--card-muted, #ccc);
  margin: 6px 0;
  opacity: 0.5;
}

.gallery-card[data-style-element-divider="gradient_line"] .hl-sep {
  display: block;
  height: 1px;
  border: none;
  background: linear-gradient(to right, var(--card-accent, #ccc), transparent);
  margin: 8px 0;
  opacity: 0.6;
}

.gallery-card[data-style-element-divider="char_asterisk"] .hl-sep {
  display: block;
  text-align: center;
  margin: 5px 0;
  font-family: monospace;
  font-size: 10px;
  opacity: 0.35;
  color: var(--card-muted, #999);
  user-select: none;
}
.gallery-card[data-style-element-divider="char_asterisk"] .hl-sep::after {
  content: "*  *  *";
}

